from math import exp, isfinite, log


def finite_number(value):
    return isinstance(value, (int, float)) and isfinite(value)


def sigmoid(score):
    if not finite_number(score):
        raise ValueError("score must be a finite number")
    if score >= 0:
        return 1.0 / (1.0 + exp(-score))
    exponential = exp(score)
    return exponential / (1.0 + exponential)


def classify(probabilities, threshold):
    if not finite_number(threshold) or not 0 <= threshold <= 1:
        raise ValueError("threshold must be in [0, 1]")
    if not probabilities:
        raise ValueError("probabilities must not be empty")
    if any(not finite_number(value) or not 0 <= value <= 1
           for value in probabilities):
        raise ValueError("probabilities must be finite and in [0, 1]")
    return [int(probability >= threshold) for probability in probabilities]


def binary_metrics(labels, predictions):
    # For this demo, an undefined precision or recall is reported as 0.0.
    if not labels or len(labels) != len(predictions):
        raise ValueError("non-empty aligned labels are required")
    if any(value not in (0, 1)
           for values in (labels, predictions) for value in values):
        raise ValueError("labels and predictions must be binary 0 or 1")
    true_positive = sum(actual == 1 and predicted == 1
                        for actual, predicted in zip(labels, predictions))
    predicted_positive = sum(predictions)
    actual_positive = sum(labels)
    precision = true_positive / predicted_positive if predicted_positive else 0.0
    recall = true_positive / actual_positive if actual_positive else 0.0
    return {"precision": precision, "recall": recall}


if __name__ == "__main__":
    # Fixed coefficients illustrate inference; no model is fitted here.
    weight = 1.0
    intercept = 0.0
    features = [log(4), log(1.5), log(2 / 3), log(0.25)]
    labels = [1, 0, 1, 0]
    probabilities = [sigmoid(weight * value + intercept) for value in features]
    print(f"probabilities={[round(value, 1) for value in probabilities]}")
    for threshold in (0.5, 0.3):
        predictions = classify(probabilities, threshold)
        metrics = binary_metrics(labels, predictions)
        print(f"threshold={threshold:.1f}, labels={predictions}")
        print(f"precision={metrics['precision']:.3f}, recall={metrics['recall']:.3f}")

from math import isfinite


def majority(labels):
    if not labels or any(label not in (0, 1) for label in labels):
        raise ValueError("non-empty binary labels are required")
    return int(2 * sum(labels) > len(labels))  # A tie selects class 0.


def gini(labels):
    probability = sum(labels) / len(labels)
    return 2 * probability * (1 - probability)


def fit_stump(xs, ys):
    if not xs or len(xs) != len(ys):
        raise ValueError("non-empty aligned data are required")
    if any(not isinstance(value, (int, float)) or not isfinite(value)
           for value in xs):
        raise ValueError("features must be finite numbers")
    majority(ys)  # Validate the binary labels before evaluating splits.
    distinct = sorted(set(xs))
    if len(distinct) < 2:
        raise ValueError("at least two distinct x values are required")
    best_score = float("inf")
    best_stump = None
    for lower, upper in zip(distinct, distinct[1:]):
        threshold = lower / 2 + upper / 2
        if threshold >= upper:
            threshold = lower
        left = [label for value, label in zip(xs, ys) if value <= threshold]
        right = [label for value, label in zip(xs, ys) if value > threshold]
        score = (len(left) * gini(left) + len(right) * gini(right)) / len(ys)
        if score < best_score:
            best_score = score
            best_stump = {
                "threshold": threshold,
                "left": majority(left),
                "right": majority(right),
            }
    return best_stump


def predict_stump(stump, value):
    if not isinstance(value, (int, float)) or not isfinite(value):
        raise ValueError("feature must be a finite number")
    return stump["left"] if value <= stump["threshold"] else stump["right"]


if __name__ == "__main__":
    features = [1, 2, 3, 4, 5, 6]
    labels = [0, 0, 0, 1, 1, 1]
    stump = fit_stump(features, labels)
    predictions = [predict_stump(stump, value) for value in (2, 5)]
    print(f"threshold={stump['threshold']:.1f}")
    print(f"stump_predictions={predictions}")
    # Supplied predictions from three imagined trees, not a trained forest.
    tree_predictions = [[0, 1], [0, 0], [1, 1]]
    votes = [majority(list(sample_votes))
             for sample_votes in zip(*tree_predictions)]
    print(f"supplied_tree_votes={votes}")

from math import isfinite
from statistics import median


def validate_values(values):
    for value in values:
        if value is not None and (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not isfinite(value)
        ):
            raise ValueError("expected finite numbers or None")


def fit_median(train_values):
    validate_values(train_values)
    observed = [value for value in train_values if value is not None]
    if not observed:
        raise ValueError("training column has no observed values")
    return float(median(observed))


def transform_missing(values, fill_value):
    validate_values(values)
    validate_values([fill_value])
    if fill_value is None:
        raise ValueError("fill value must be observed")
    return [
        (float(fill_value if value is None else value), int(value is None))
        for value in values
    ]


if __name__ == "__main__":
    training = [10, None, 20, 100]
    frozen_median = fit_median(training)
    print(f"train_median={frozen_median:.1f}")
    print("validation=", transform_missing([None, 0, 200], frozen_median), sep="")
    print("test=", transform_missing([None, 30], frozen_median), sep="")
    print(f"median_after_transform={frozen_median:.1f}")

def validate_categories(values):
    if any(value is not None and not isinstance(value, str) for value in values):
        raise ValueError("categories must be strings or None")


def fit_categories(train_values):
    validate_categories(train_values)
    if not train_values:
        raise ValueError("training values must not be empty")
    return tuple(sorted({value for value in train_values if value is not None}))


def transform_categories(values, vocabulary):
    validate_categories(values)
    validate_categories(vocabulary)
    if None in vocabulary or len(set(vocabulary)) != len(vocabulary):
        raise ValueError("vocabulary must contain unique strings")
    encoded = []
    for value in values:
        known = [int(value == category) for category in vocabulary]
        missing = int(value is None)
        unknown = int(value is not None and value not in vocabulary)
        encoded.append(known + [missing, unknown])
    return encoded


if __name__ == "__main__":
    vocabulary = fit_categories(["red", "blue", None, "red"])
    print("vocabulary=", vocabulary, sep="")
    print("validation=", transform_categories(["red", "green", None], vocabulary), sep="")
    print("test=", transform_categories(["blue", "__UNKNOWN__"], vocabulary), sep="")
    print("vocabulary_after_transform=", vocabulary, sep="")

