from math import isfinite


def validate_probabilities(probabilities):
    if not probabilities or any(type(value) not in (int, float)
                                or not isfinite(value) or not 0 <= value <= 1
                                for value in probabilities):
        raise ValueError("non-empty finite probabilities in [0, 1] required")


def validate_pairs(labels, probabilities):
    validate_probabilities(probabilities)
    if len(labels) != len(probabilities) or any(
        type(label) is not int or label not in (0, 1) for label in labels
    ):
        raise ValueError("aligned integer binary labels required")


def reliability(labels, probabilities):
    validate_pairs(labels, probabilities)
    rows = []
    for upper in [False, True]:
        members = [(label, probability) for label, probability in zip(labels, probabilities)
                   if (probability >= 0.5) == upper]
        support = len(members)
        rows.append({
            "support": support,
            "mean": sum(probability for _, probability in members) / support if support else None,
            "rate": sum(label for label, _ in members) / support if support else None,
        })
    return rows


def fit_histogram(labels, probabilities):
    rows = reliability(labels, probabilities)
    if any(row["support"] == 0 for row in rows):
        raise ValueError("both calibration bins need observations")
    return tuple(row["rate"] for row in rows)


def calibrate(probabilities, rates):
    validate_probabilities(probabilities)
    validate_probabilities(rates)
    if len(rates) != 2:
        raise ValueError("exactly two bin rates required")
    return [rates[int(probability >= 0.5)] for probability in probabilities]


def brier(labels, probabilities):
    validate_pairs(labels, probabilities)
    return sum((probability - label) ** 2
               for label, probability in zip(labels, probabilities)) / len(labels)


calibration_ids = list(range(8))
test_ids = list(range(8, 12))
assert set(calibration_ids).isdisjoint(test_ids)
calibration_labels = [0, 0, 0, 1, 0, 1, 1, 1]
calibration_probabilities = [0.05] * 4 + [0.95] * 4
rates = fit_histogram(calibration_labels, calibration_probabilities)
test_labels = [0, 1, 0, 1]
test_probabilities = [0.05, 0.05, 0.95, 0.95]
adjusted = calibrate(test_probabilities, rates)
print("calibration rates:", rates)
print("test before:", reliability(test_labels, test_probabilities))
print("test after:", reliability(test_labels, adjusted))
print(f"Brier before={brier(test_labels, test_probabilities):.4f}")
print(f"Brier after={brier(test_labels, adjusted):.4f}")

def group_report(labels, predicted):
    if not labels or len(labels) != len(predicted):
        raise ValueError("non-empty aligned labels required")
    if any(type(label) is not int or label not in (0, 1)
           for label in [*labels, *predicted]):
        raise ValueError("integer binary labels required")
    counts = {"tp": 0, "fp": 0, "tn": 0, "fn": 0}
    names = {(1, 1): "tp", (0, 1): "fp", (0, 0): "tn", (1, 0): "fn"}
    for truth, guess in zip(labels, predicted):
        counts[names[truth, guess]] += 1
    positives = counts["tp"] + counts["fn"]
    alerts = counts["tp"] + counts["fp"]
    return {
        **counts,
        "support": len(labels),
        "positives": positives,
        "alerts": alerts,
        "precision": counts["tp"] / alerts if alerts else None,
        "recall": counts["tp"] / positives if positives else None,
        "error_rate": (counts["fp"] + counts["fn"]) / len(labels),
    }


def slice_reports(labels, predicted, groups):
    overall = group_report(labels, predicted)
    if len(groups) != len(labels) or any(type(group) is not str or not group.strip()
                                        for group in groups):
        raise ValueError("aligned non-empty group names required")
    reports = {}
    for group in sorted(set(groups)):
        indices = [index for index, value in enumerate(groups) if value == group]
        reports[group] = group_report([labels[index] for index in indices],
                                      [predicted[index] for index in indices])
    return overall, reports


validation_labels = [1, 1, 0, 0, 1, 1, 0, 0]
validation_predictions = [1, 1, 1, 0, 0, 0, 1, 0]
groups = ["desktop"] * 4 + ["mobile"] * 4
overall, reports = slice_reports(validation_labels, validation_predictions, groups)
for group, report in [("overall", overall), *reports.items()]:
    print(group, report)
# Synthetic IDs only; do not copy raw private records into error logs.
error_log = [(f"case-{index + 1}", groups[index], "FN" if truth == 1 else "FP")
             for index, (truth, guess) in enumerate(zip(validation_labels, validation_predictions))
             if truth != guess]
print("errors:", error_log)

