import json
from math import isfinite


FEATURES = ["size", "age"]


def finite_number(value):
    return type(value) in (int, float) and isfinite(value)


def validate_model(model):
    keys = {"schema", "version", "features", "preprocess", "coefficients", "intercept"}
    if type(model) is not dict or set(model) != keys:
        raise ValueError("invalid model keys")
    if model["schema"] != "teaching-linear" or type(model["version"]) is not int or model["version"] != 1:
        raise ValueError("unsupported schema or version")
    if model["features"] != FEATURES:
        raise ValueError("ordered features must be size, age")
    preprocess = model["preprocess"]
    if type(preprocess) is not dict or set(preprocess) != {"mean", "scale"}:
        raise ValueError("invalid preprocessing schema")
    for vector in [preprocess["mean"], preprocess["scale"], model["coefficients"]]:
        if type(vector) is not list or len(vector) != 2 or not all(map(finite_number, vector)):
            raise ValueError("two finite numbers required per vector")
    if not finite_number(model["intercept"]) or any(scale <= 0 for scale in preprocess["scale"]):
        raise ValueError("finite intercept and positive scales required")


def predict(model, rows):
    validate_model(model)
    if not rows:
        raise ValueError("non-empty rows required")
    predictions = []
    for row in rows:
        if type(row) is not dict or set(row) != set(FEATURES) or not all(map(finite_number, row.values())):
            raise ValueError("row must contain exactly two finite named features")
        value = model["intercept"]
        for index, feature in enumerate(FEATURES):
            standardized = (row[feature] - model["preprocess"]["mean"][index]) / model["preprocess"]["scale"][index]
            value += model["coefficients"][index] * standardized
        if not isfinite(value):
            raise ValueError("non-finite prediction")
        predictions.append(value)
    return predictions


def reject_constant(value):
    raise ValueError("non-standard JSON number: " + value)


def unique_keys(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON key: " + key)
        result[key] = value
    return result


def load_model(serialized):
    model = json.loads(serialized, parse_constant=reject_constant, object_pairs_hook=unique_keys)
    validate_model(model)
    return model


model = {
    "schema": "teaching-linear",
    "version": 1,
    "features": ["size", "age"],
    "preprocess": {"mean": [50.0, 10.0], "scale": [10.0, 5.0]},
    "coefficients": [2.0, -1.0],
    "intercept": 100.0,
}
rows = [{"size": 60.0, "age": 15.0}, {"size": 40.0, "age": 5.0}]
before = predict(model, rows)
serialized = json.dumps(model, allow_nan=False, sort_keys=True)
reloaded = load_model(serialized)
after = predict(reloaded, rows)
print("before:", before)
print("after:", after)
print("round_trip_equal:", before == after)
print("size_plus_one:", predict(reloaded, [{"size": 61.0, "age": 15.0}]))

