    mutated = {**call, "arguments": {"status": "draft"}}
    print(policy.execute("alice", "request-1", mutated, 3, 20, approval))
    policy.permissions["alice"].clear()
    print(policy.execute("alice", "request-1", call, 4, 20, approval))


