def grade(task, solver, observed):
    # Task authors must define a prompt and a concrete expected report.
    expected = task.get("expected_report")
    if not task.get("prompt", "").strip() or not isinstance(expected, dict) or not expected:
        raise TaskDefinitionError("Define the requested report before scoring")
    # solver holds claims/trace for diagnosis, never authoritative evidence.
    # observed comes from the harness recorder, not a solver-supplied dictionary.
    if any(tool not in {"search", "read_document"} for tool in observed["tools"]):
        return "fail:permission"
    if len(observed["tools"]) > 5 or not 0 <= observed["seconds"] <= 2:
        return "fail:budget"
    report = observed.get("report")
    if not isinstance(report, dict) or any(k not in report or report[k] != v for k, v in expected.items()):
        return "fail:outcome"
    return "pass"

