import json
def bounded_retry(outcomes, max_attempts=3, deadline_ms=100):
    elapsed, calls = 0, 0
    for outcome in outcomes:
        if calls >= max_attempts or elapsed + 10 > deadline_ms:
            return {"status": "budget_exhausted", "calls": calls, "elapsed_ms": elapsed}
        elapsed += 10
        calls += 1
        if outcome == "ok":
            return {"status": "ok", "calls": calls, "elapsed_ms": elapsed}
        if outcome not in {"timeout", "rate_limited"}:
            return {"status": outcome, "calls": calls, "elapsed_ms": elapsed}
        wait = 10 * 2 ** (calls - 1)
        if calls == max_attempts or elapsed + wait + 10 > deadline_ms:
            return {"status": "budget_exhausted", "calls": calls, "elapsed_ms": elapsed}
        elapsed += wait
    return {"status": "no_more_fixture_outcomes", "calls": calls, "elapsed_ms": elapsed}
print(json.dumps([bounded_retry(["timeout", "ok"]), bounded_retry(["forbidden", "ok"]),
                  bounded_retry(["timeout"] * 5, deadline_ms=25)]))

