def estimated_cost(card, input_tokens, output_tokens):
    if input_tokens < 0 or output_tokens < 0:
        raise ValueError("negative token count")
    return (input_tokens * card["input_rate"] + output_tokens * card["output_rate"]) / 1_000_000
def route(classification):
    permitted = [c for c in cards if c["license_checked"] and c["revision"]
                 and classification in c["classifications"]]
    if not permitted:
        return None
    chosen = min(permitted, key=lambda c: estimated_cost(c, 1000, 500))
    return {"model": chosen["id"], "assumed_cost": estimated_cost(chosen, 1000, 500)}
print(json.dumps({"public": route("public"), "restricted": route("restricted"),
                  "unknown": route("secret")}))
